import { buildSearchUrl } from '../lib/maps';
import type { Venue, VenueStatus } from '../types';

/**
 * CURATED VENUE DATASET — real places in Jakarta.
 *
 * How these records were put together (checked 2026-11-04):
 * - Every venue is a real, named place taken from a published source
 *   (official Jakarta tourism pages, news outlets, or editorial lists).
 *   `sourceUrl` / `sourceName` say where the details came from.
 * - Addresses are copied from those sources. Coordinates are NOT included:
 *   none were taken from a reliable source, so none were invented.
 * - Prices are per person in IDR.
 *   - `priceType`: 'free' (no entry fee), 'ticket' (entry ticket), or
 *     'purchase_required' (what a person typically spends on food/drinks).
 *   - `priceConfidence`: 'verified' only when the figure comes from the venue
 *     or its operator (as reported); 'estimated' for third-party or older
 *     figures; unknown prices use `priceUnknown: true` and are never guessed.
 *   - When a source only gives a floor ("mulai Rp400 ribu") priceMax equals
 *     priceMin and `priceNote` says so.
 * - `status: 'active'` only when a 2025–2026 source mentions the venue as
 *   operating. Venues with only older sources are 'inactive' and flagged
 *   `needsVerification`; the planner never uses inactive venues.
 * - Transit access is only filled in when a source states it. Distances and
 *   walking times come from the official Jakarta tourism site (enjoy.jakarta.go.id).
 * - `verifiedAt` is left empty on purpose: nobody has checked these records
 *   against the Google Maps listing in person yet. `lastCheckedAt` is the
 *   date the sources were reviewed.
 * - Vibes, activities and visit durations are planning tags chosen for the
 *   date engine, not facts claimed by the sources.
 *
 * `googleMapsUrl` is built with the shared Maps URL helper (public search URL,
 * no API, no scraping).
 */

