type Seed = Omit<Venue, 'city' | 'googleMapsUrl' | 'status' | 'lastCheckedAt'> & { status?: VenueStatus };

function venue(seed: Seed): Venue {
  const base = { ...seed, city: 'Jakarta', status: seed.status ?? 'active', lastCheckedAt: DATASET_CHECKED_AT };
  return { ...base, googleMapsUrl: buildSearchUrl(base) };
}

/** Free entry. Reported by a third party, so 'estimated' rather than verified. */
const free = { priceMin: 0, priceMax: 0, priceType: 'free', priceConfidence: 'estimated' } as const;
/** Spending on food/drinks, third-party estimate. */
const spend = (min: number, max: number) =>
  ({ priceMin: min, priceMax: max, priceType: 'purchase_required', priceConfidence: 'estimated' }) as const;
/** Entry ticket. */
const ticket = (min: number, max: number, confidence: 'verified' | 'estimated' = 'estimated') =>
  ({ priceMin: min, priceMax: max, priceType: 'ticket', priceConfidence: confidence }) as const;
/** Price not published anywhere we could find. */
const unknownPrice = { priceMin: 0, priceMax: 0, priceUnknown: true, priceConfidence: 'unknown' } as const;
/** Older sources only: kept for reference, never planned. */
const unverified = { status: 'inactive', needsVerification: true } as const;

const transit = (stationName: string, transitType: 'transjakarta' | 'mrt' | 'lrt' | 'krl', distanceMeters?: number, walkingMinutes?: number) => ({
  stationName,
  transitType,
  ...(distanceMeters !== undefined ? { distanceMeters } : {}),
  ...(walkingMinutes !== undefined ? { walkingMinutes } : {}),
  // Only rows with a stated distance/time from an official source are marked as checked.
  ...(distanceMeters !== undefined || walkingMinutes !== undefined ? { verifiedAt: DATASET_CHECKED_AT } : {}),
});

